import { MouseEvent, useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import { Formatter } from '../../../types/formatter.js';
import { MouseCoordinate } from '../../../types/overlays.js';
import { TooltipItem } from '../../../types/tooltip.js';
import { groupOverlappingMarkers } from '../functions/group-overlapping-markers.js';
import { THRESHOLD_MESSAGES } from '../messages/messages.js';
import { ThresholdMarker } from '../ThresholdBar.js';

const TOOLTIP_Y_OFFSET = 32;

function getMarkerValue(marker: ThresholdMarker, formatter: Formatter) {
  return marker.y0 === marker.y1
    ? formatter(marker.y0)
    : `${formatter(marker.y0)} – ${formatter(marker.y1)}`;
}

export function useThresholdBarTooltip(
  markers: ThresholdMarker[],
  formatter: (value: number) => string,
  onHover?: (id: string | undefined) => void,
) {
  const groupedMarkers = useMemo(
    () => groupOverlappingMarkers(markers),
    [markers],
  );
  const intl = useIntl();

  const [hoveredIndex, setHoveredIndex] = useState<number | undefined>();
  const [tooltipPosition, setTooltipPosition] = useState<MouseCoordinate>();
  const [tooltipItems, setTooltipItems] = useState<TooltipItem[]>([]);

  function handleMouseMove(event: MouseEvent, index: number) {
    setHoveredIndex(index);

    const tooltipPosition = {
      x: event.clientX,
      y: event.clientY + TOOLTIP_Y_OFFSET,
    };
    const marker = markers[index];

    const belongingGroup = groupedMarkers.find((group) =>
      group.some((item) => item.y1 === marker.y1 && item.y0 === marker.y0),
    );

    if (belongingGroup) {
      const tooltipItems = belongingGroup.map((item, index) => ({
        id: item.id,
        color: { Default: item.color },
        values: [getMarkerValue(item, formatter)],
        name:
          item.label ?? intl.formatMessage(THRESHOLD_MESSAGES.thresholdLabel),
      }));
      setTooltipPosition(tooltipPosition);
      setTooltipItems(tooltipItems);
      onHover?.(marker.id);
    }
  }

  function handleMouseLeave() {
    setHoveredIndex(undefined);
    setTooltipItems([]);
    onHover?.(undefined);
  }

  return {
    showTooltip: hoveredIndex !== undefined && tooltipPosition,
    tooltipPosition,
    tooltipItems,
    handleMouseMove,
    handleMouseLeave,
  };
}
